from flask import Flask, render_template, request, jsonify, stream_with_context, Response, abort
import os
import json
from xai_sdk import Client
from xai_sdk.chat import user, system, assistant, image
from dotenv import load_dotenv
from typing import List, Dict, Any, Optional, Generator
import grpc
from grpc import StatusCode

load_dotenv()

XAI_API_KEY = os.getenv("XAI_API_KEY")
if XAI_API_KEY is None:
    raise ValueError("XAI_API_KEY environment variable not set")

client = Client(api_key=XAI_API_KEY)

app = Flask(__name__)

MODEL_DEFAULT = "grok-4-1-fast"
USE_ENCRYPTED_CONTENT_DEFAULT = True
STORE_MESSAGES_DEFAULT = True
DETAIL_DEFAULT = "high"
MESSAGES_KEY = "messages"
MODEL_KEY = "model"
USE_ENCRYPTED_CONTENT_KEY = "use_encrypted_content"
STORE_MESSAGES_KEY = "store_messages"
ROLE_KEY = "role"
CONTENT_KEY = "content"
SYSTEM_ROLE = "system"
USER_ROLE = "user"
ASSISTANT_ROLE = "assistant"
TYPE_KEY = "type"
INPUT_TEXT_TYPE = "input_text"
TEXT_KEY = "text"
INPUT_IMAGE_TYPE = "input_image"
IMAGE_URL_KEY = "image_url"
DETAIL_KEY = "detail"
MESSAGE_ATTR = "message"
CONTENT_ATTR = "content"
CHOICES_ATTR = "choices"
REASONING_ATTR = "reasoning"
ENCRYPTED_CONTENT_ATTR = "encrypted_content"
RESOURCE_EXHAUSTED_MSG = "Your xAI credit is exhausted. Please top up in the xAI console!"
API_ERROR = "API_ERROR"
XAI_CREDIT_EXHAUSTED = "XAI_CREDIT_EXHAUSTED"
ERROR_KEY = "error"
MESSAGE_ERROR_KEY = "message"
HOST = "0.0.0.0"
PORT = 5000
INDEX_TEMPLATE = "index.html"
CHAT_PATH = "/chat"
ROOT_PATH = "/"
POST_METHOD = "POST"
EVENT_STREAM_MIMETYPE = "text/event-stream"

@app.route(ROOT_PATH)
def index() -> str:
    return render_template(INDEX_TEMPLATE)

@app.route(CHAT_PATH, methods=[POST_METHOD])
def chat_request() -> Response:
    if not request.is_json:
        abort(400, description="Request must be JSON")
    data: Dict[str, Any] = request.json
    messages: List[Dict[str, Any]] = data.get(MESSAGES_KEY, [])
    model: str = data.get(MODEL_KEY, MODEL_DEFAULT)
    use_encrypted_content: bool = data.get(USE_ENCRYPTED_CONTENT_KEY, USE_ENCRYPTED_CONTENT_DEFAULT)
    store_messages: bool = data.get(STORE_MESSAGES_KEY, STORE_MESSAGES_DEFAULT)

    try:
        chat = client.chat.create(
            model=model,
            store_messages=store_messages,
            use_encrypted_content=use_encrypted_content
        )

        for msg in messages:
            if not isinstance(msg, dict):
                continue
            role: Optional[str] = msg.get(ROLE_KEY)
            content: Any = msg.get(CONTENT_KEY)
            if role is None or content is None:
                continue
            if role == SYSTEM_ROLE:
                if isinstance(content, str):
                    chat.append(system(content))
            elif role == USER_ROLE:
                if isinstance(content, list):
                    parts: List[Any] = []
                    for part in content:
                        if not isinstance(part, dict):
                            continue
                        part_type: Optional[str] = part.get(TYPE_KEY)
                        if part_type == INPUT_TEXT_TYPE:
                            text: Optional[str] = part.get(TEXT_KEY)
                            if text is not None:
                                parts.append(text)
                        elif part_type == INPUT_IMAGE_TYPE:
                            img_url: Optional[str] = part.get(IMAGE_URL_KEY)
                            dtl: str = part.get(DETAIL_KEY, DETAIL_DEFAULT)
                            if img_url is not None:
                                parts.append(image(image_url=img_url, detail=dtl))
                    if parts:
                        chat.append(user(*parts))
                elif isinstance(content, str):
                    chat.append(user(content))
            elif role == ASSISTANT_ROLE:
                if isinstance(content, str):
                    chat.append(assistant(content))

        def generate() -> Generator[str, None, None]:
            try:
                response = chat.sample()
                content_text: str = ""
                try:
                    content_text = response.choices[0].message.content
                except (AttributeError, IndexError):
                    pass
                try:
                    content_text = response.message.content
                except AttributeError:
                    pass

                if content_text:
                    yield f"data: {json.dumps({'content': content_text, 'id': getattr(response, 'id', '')})}\n\n"

                if use_encrypted_content:
                    reasoning = getattr(response, REASONING_ATTR, None)
                    if reasoning and hasattr(reasoning, ENCRYPTED_CONTENT_ATTR):
                        yield f"data: {json.dumps({'encrypted_reasoning': getattr(reasoning, ENCRYPTED_CONTENT_ATTR)})}\n\n"
                yield "data: [DONE]\n\n"
            except grpc.RpcError as rpc_error:
                if rpc_error.code() == StatusCode.RESOURCE_EXHAUSTED:
                    yield f"data: {json.dumps({ERROR_KEY: XAI_CREDIT_EXHAUSTED, MESSAGE_ERROR_KEY: RESOURCE_EXHAUSTED_MSG})}\n\n"
                else:
                    yield f"data: {json.dumps({ERROR_KEY: API_ERROR, MESSAGE_ERROR_KEY: str(rpc_error)})}\n\n"
            except Exception as e:
                yield f"data: {json.dumps({ERROR_KEY: API_ERROR, MESSAGE_ERROR_KEY: str(e)})}\n\n"

        return Response(stream_with_context(generate()), mimetype=EVENT_STREAM_MIMETYPE)
    except Exception as e:
        return jsonify({ERROR_KEY: str(e)}), 500

if __name__ == "__main__":
    app.run(host=HOST, port=PORT, debug=False)

